,{type:"checkbox",checked:formData.is_featured,onChange:e=>setFormData(_objectSpread(_objectSpread({},formData),{},{is_featured:e.target.checked})),className:"\r w-4\r h-4\r accent-red-500\r "}),/*#__PURE__*/_jsx("div",{className:"\r w-9\r h-9\r bg-red-100\r text-red-600\r rounded-lg\r flex\r items-center\r justify-center\r ",children:/*#__PURE__*/_jsx(FiStar,{size:16})}),/*#__PURE__*/_jsxs("div",{children:[/*#__PURE__*/_jsx("p",{className:"text-sm font-semibold text-blue-900",children:"Featured Video"}),/*#__PURE__*/_jsx("p",{className:"text-[10px] text-blue-300 mt-0.5",children:"Highlight this video on the website"})]})]})]}),/*#__PURE__*/_jsxs("div",{className:"\r mt-6\r pt-4\r border-t\r border-blue-200\r flex\r items-center\r justify-end\r gap-3\r ",children:[/*#__PURE__*/_jsx("button",{type:"button",onClick:handleCloseModal,disabled:submitting,className:"\r h-10\r px-4\r bg-white\r border\r border-blue-200\r text-blue-400\r rounded-lg\r text-sm\r font-semibold\r hover:bg-blue-50\r transition\r ",children:"Cancel"}),/*#__PURE__*/_jsx("button",{type:"submit",disabled:submitting,className:"\r min-w-[110px]\r h-10\r px-5\r bg-red-600\r text-white\r rounded-lg\r text-sm\r font-semibold\r hover:bg-red-700\r disabled:opacity-50\r disabled:cursor-not-allowed\r transition\r ",children:submitting?editingVideo?'Updating...':'Adding...':editingVideo?'Update Video':'Add Video'})]})]})})]});};export default AdminVideos;

